var doT = (function() {
    var version = "1.1.2";
    var templateSettings = {
        evaluate: /\{\{([\s\S]+?)\}\}/g,
        interpolate: /\{\{=([\s\S]+?)\}\}/g,
        encode: /\{\{!([\s\S]+?)\}\}/g,
        use: /\{\{#([\s\S]+?)\}\}/g,
        define: /\{\{##\s*([\w$\.]+)\s*(\:|=)([\s\S]+?)#\}\}/g,
        conditional: /\{\{\?(\?)?\s*([\s\S]*?)\s*\}\}/g,
        iterate: /\{\{~\s*(?:\}\}|([\s\S]+?)\s*\:\s*([\w$]+)\s*(?:\:\s*([\w$]+))?\s*\}\})/g,
        varname: "it",
        strip: true,
        append: true
    };

    function encodeHTMLSource(str) {
        var encodeMap = { "&": "&#38;", "<": "&#60;", ">": "&#62;", '"': "&#34;", "'": "&#39;", "/": "&#47;" };
        return str.replace(/&(?!#?\w+;)|<|>|"|'|\//g, function(match) { return encodeMap[match] || match; });
    }

    function extend(obj, src) {
        for (var key in src) {
            if (src.hasOwnProperty(key)) obj[key] = src[key];
        }
        return obj;
    }

    function compile(tmpl, def) {
        var settings = def || templateSettings;
        var append = settings.append ? "return p.join('');" : "return p;";
        var str = tmpl;

        str = str.replace(/\r/g, "\\r").replace(/\n/g, "\\n").replace(/\t/g, "\\t");
        if (settings.strip) str = str.replace(/'|\\/g, "\\$&");

        str = str.replace(settings.encode || /\{\{!([\s\S]+?)\}\}/g, function(match, code) {
            return "' + doT.encodeHTMLSource(" + code.replace(/\\n/g, "").replace(/\\r/g, "") + ") + '";
        });

        str = str.replace(settings.interpolate || /\{\{=([\s\S]+?)\}\}/g, function(match, code) {
            return "' + (" + code.replace(/\\n/g, "").replace(/\\r/g, "") + ") + '";
        });

        str = str.replace(settings.evaluate || /\{\{([\s\S]+?)\}\}/g, function(match, code) {
            return "';\n" + code.replace(/\\n/g, "").replace(/\\r/g, "") + "\np.push('";
        });

        str = str.replace(settings.conditional || /\{\{\?(\?)?\s*([\s\S]*?)\s*\}\}/g, function(match, isElse, code) {
            return isElse ? "';\n}else{p.push('" : "';\nif(" + code + "){p.push('";
        });

        str = str.replace(settings.iterate || /\{\{~\s*(?:\}\}|([\s\S]+?)\s*\:\s*([\w$]+)\s*(?:\:\s*([\w$]+))?\s*\}\})/g, function(match, arr, key, val) {
            return arr ? "';\nfor(var " + (val || "i") + " in " + arr + "){if(" + arr + ".hasOwnProperty(" + (val || "i") + ")){var " + key + "=" + arr + "[" + (val || "i") + "];p.push('" : "';\n}p.push('";
        });

        var fnstr = "var p=[];var print=function(){p.push.apply(p,arguments);};p.push('" + str + "');return p.join('');";
        return new Function(settings.varname, fnstr);
    }

    return {
        version: version,
        templateSettings: templateSettings,
        encodeHTMLSource: encodeHTMLSource,
        template: function(tmpl, def) {
            return compile(tmpl, extend({}, templateSettings, def));
        },
        compile: compile
    };
})();